import json,re,random,chess,sys
RULES=json.load(open('/app/re.json'))
def sol(fen):
    for p,r in RULES: fen=re.sub(p,r,fen)
    return [" ".join(x.split(" ")[:-2]) for x in fen.split("\n")]
def check(fen):
    ours=sol(fen)
    b=chess.Board(fen); exp=set()
    for m in b.legal_moves:
        if m.promotion and m.promotion!=chess.QUEEN: continue
        c=b.copy(); c.push(m); exp.add(" ".join(c.fen().split(" ")[:-2]))
    bad=[x for x in ours if not(x in exp or x.rpartition(" ")[0]+" -" in exp)]
    if bad or len(ours)!=len(exp):
        print("FAIL",fen); print(" extra:",bad)
        got={x.rpartition(" ")[0] for x in ours}
        print(" missing:",[e for e in exp if e.rpartition(" ")[0] not in got])
        print(" n ours",len(ours),"exp",len(exp))
        return False
    return True
random.seed(int(sys.argv[1]) if len(sys.argv)>1 else 0)
n=0;fails=0
for g in range(int(sys.argv[2]) if len(sys.argv)>2 else 40):
    b=chess.Board()
    for ply in range(random.randint(0,120)):
        ms=list(b.legal_moves)
        if not ms: break
        if b.turn==chess.WHITE:
            n+=1
            if not check(b.fen()):
                fails+=1
                if fails>5: sys.exit(1)
        b.push(random.choice(ms))
print("checked",n,"fails",fails)
